+    public static LegacySemanticTextField randomSemanticText(String fieldName, Model model, List<String> inputs, XContentType contentType)
+        throws IOException {
+        ChunkedInferenceServiceResults results = switch (model.getTaskType()) {
+            case TEXT_EMBEDDING -> randomInferenceChunkedTextEmbeddingFloatResults(model, inputs);
+            case SPARSE_EMBEDDING -> randomSparseEmbeddings(inputs);
+            default -> throw new AssertionError("invalid task type: " + model.getTaskType().name());
+        };
+        return semanticTextFieldFromChunkedInferenceResults(fieldName, model, inputs, results, contentType);
+    }
+
+    public static LegacySemanticTextField semanticTextFieldFromChunkedInferenceResults(
+        String fieldName,
+        Model model,
+        List<String> inputs,
+        ChunkedInferenceServiceResults results,
+        XContentType contentType
+    ) {
+        return new LegacySemanticTextField(
+            fieldName,
+            inputs,
+            new LegacySemanticTextField.InferenceResult(
+                model.getInferenceEntityId(),
+                new LegacySemanticTextField.ModelSettings(model),
+                LegacySemanticTextField.toSemanticTextFieldChunks(List.of(results), contentType)
+            ),
+            contentType
+        );
+    }
