+                            listSnapshotsResponse.evaluate("snapshots.1.snapshot")
+                        )
+                    );
+                    assertEquals("SUCCESS", listSnapshotsResponse.evaluate("snapshots.0.state"));
+                    assertEquals("SUCCESS", listSnapshotsResponse.evaluate("snapshots.1.state"));
