+     */
+    private Block buildIntermediateBlock() {
+        if (categorizer.getCategoryCount() == 0) {
+            return blockFactory.newConstantNullBlock(seenNull ? 1 : 0);
+        }
+        try (BytesStreamOutput out = new BytesStreamOutput()) {
+            out.writeBoolean(seenNull);
