+                return result.build();
+            }
+        }
+
+        int process(BytesRef v) {
+            var category = categorizer.computeCategory(v.utf8ToString(), analyzer);
+            if (category == null) {
+                seenNull = true;
+                return NULL_ORD;
+            }
+            return category.getId() + 1;
+        }
+
+        @Override
+        public void close() {
+            analyzer.close();
+        }
+    }
