+        volatile boolean isActive;
+
+        int checkSomeStaticMethodIntCallCount = 0;
+        int checkSomeStaticMethodIntStringCallCount = 0;
+        int checkSomeInstanceMethodCallCount = 0;
+
+        int checkCtorCallCount = 0;
