+        double maxNegX = Double.NEGATIVE_INFINITY;
+        double minPosX = Double.POSITIVE_INFINITY;
+        double maxPosX = Double.NEGATIVE_INFINITY;
+        for (int i = 0; i < 1000; i++) {
