+    public void testRescoreOversampleUsedWithoutQuantization() {
+        DenseVectorFieldMapper.ElementType elementType = randomFrom(FLOAT, BYTE);
+        DenseVectorFieldType nonQuantizedField = new DenseVectorFieldType(
